import{_ as e,o,c as a,a3 as i}from"./chunks/framework.jVlskimI.js";const g=JSON.parse('{"title":"🏝️ 欢迎来到空岛世界","description":"","frontmatter":{},"headers":[],"relativePath":"Sky.md","filePath":"Sky.md"}'),r={name:"Sky.md"};function l(d,t,s,n,c,h){return o(),a("div",{"data-pagefind-body":!0},t[0]||(t[0]=[i('<h1 id="🏝️-欢迎来到空岛世界" tabindex="-1">🏝️ 欢迎来到空岛世界 <a class="header-anchor" href="#🏝️-欢迎来到空岛世界" aria-label="Permalink to &quot;🏝️ 欢迎来到空岛世界&quot;">​</a></h1><blockquote><p>从一座孤岛开始，创造属于你的虚空奇迹！</p></blockquote><h2 id="✨-空岛特色功能一览" tabindex="-1">✨ 空岛特色功能一览 <a class="header-anchor" href="#✨-空岛特色功能一览" aria-label="Permalink to &quot;✨ 空岛特色功能一览&quot;">​</a></h2><h3 id="🏝️-岛屿管理" tabindex="-1">🏝️ 岛屿管理 <a class="header-anchor" href="#🏝️-岛屿管理" aria-label="Permalink to &quot;🏝️ 岛屿管理&quot;">​</a></h3><ul><li><strong>创建岛屿</strong>：输入 <code>/is create</code> 选择你喜欢的蓝图，即刻生成你的私人空岛。</li><li><strong>设置重生点</strong>：站在你喜欢的地方，输入 <code>/is setspawn</code>，以后死亡或传送就回到这里。</li><li><strong>快速回家</strong>：无论在哪，输入 <code>/is spawn</code> 瞬间返回岛屿。</li><li><strong>删除岛屿</strong>：如果需要重新开始，输入 <code>/is delete</code>（聊胜于无的二次确认），岛屿会彻底清空。</li></ul><h3 id="👥-与好友共建" tabindex="-1">👥 与好友共建 <a class="header-anchor" href="#👥-与好友共建" aria-label="Permalink to &quot;👥 与好友共建&quot;">​</a></h3><ul><li><strong>邀请伙伴</strong>：输入 <code>/is invite 玩家名字</code>，对方同意后就能加入你的岛屿。</li><li><strong>踢出成员</strong>：身为岛主，输入 <code>/is kick 玩家名字</code> 可以把捣乱的成员请出去。</li><li><strong>精细权限</strong>：输入 <code>/is setperms</code> 打开设置面板，你可以决定每位成员： <ul><li>能否破坏/放置方块</li><li>能否使用箱子、工作台、附魔台等</li><li>能否攻击生物或玩家</li><li>能否引发爆炸、火焰蔓延等事件</li></ul></li><li><strong>社区感</strong>：访客进入你的岛屿会收到自定义欢迎语和底部提示，离开时也有提醒。</li></ul><h3 id="🌍-改变岛屿群系" tabindex="-1">🌍 改变岛屿群系 <a class="header-anchor" href="#🌍-改变岛屿群系" aria-label="Permalink to &quot;🌍 改变岛屿群系&quot;">​</a></h3><ul><li>想要你的岛屿变成竹林、向日葵平原、甚至蘑菇岛？输入 <code>/is biome</code> 打开群系选择器。</li><li>上百种群系任你挑选，修改后会立刻生效，一块净土就能变成你想要的风格！</li></ul><h3 id="💬-个人化岛屿提示" tabindex="-1">💬 个人化岛屿提示 <a class="header-anchor" href="#💬-个人化岛屿提示" aria-label="Permalink to &quot;💬 个人化岛屿提示&quot;">​</a></h3><ul><li>输入 <code>/is tip</code> 设置你的岛屿专属<strong>欢迎语</strong>（访客进入时显示）和<strong>底部常驻提示</strong>（访客在岛上时一直显示）。</li><li>支持变量 <code>{name}</code>（岛主名）和 <code>{visitor}</code>（访客名），让消息更亲切。</li></ul><h3 id="🎁-便利菜单与礼包" tabindex="-1">🎁 便利菜单与礼包 <a class="header-anchor" href="#🎁-便利菜单与礼包" aria-label="Permalink to &quot;🎁 便利菜单与礼包&quot;">​</a></h3><ul><li>新玩家会获得一个特殊的 <strong>“菜单钟”</strong>，右键点击即可打开功能面板，不用记指令也能操作。</li><li>主菜单集成岛屿管理、传送、权限设置、群系修改、挑战入口等。</li></ul><h3 id="⛏️-自动刷矿机-特色玩法" tabindex="-1">⛏️ 自动刷矿机（特色玩法） <a class="header-anchor" href="#⛏️-自动刷矿机-特色玩法" aria-label="Permalink to &quot;⛏️ 自动刷矿机（特色玩法）&quot;">​</a></h3><ul><li>岩浆碰到水生成圆石时，会有概率<strong>自动变成各种矿石</strong>！（钻石、铁、金、煤、红石、青金石、铜、下界石英）</li><li>如果你在深层区域（Y 坐标 Y ≤ 20）刷石，圆石会变成<strong>深板岩圆石</strong>，随机到的矿石也会自动升级为<strong>深层矿石变种</strong>（如深层钻石矿）。</li><li>不用挖矿也能发家致富！</li></ul><h3 id="🔪-刷怪机制深度优化" tabindex="-1">🔪 刷怪机制深度优化 <a class="header-anchor" href="#🔪-刷怪机制深度优化" aria-label="Permalink to &quot;🔪 刷怪机制深度优化&quot;">​</a></h3><ul><li>空岛服针对基岩版刷怪效率低的问题进行了<strong>专项调优</strong>，大幅提升怪物在岛屿平台上的生成速度与密度。</li><li>苦力怕、骷髅、僵尸、蜘蛛等敌对生物会<strong>更稳定地刷新</strong>，确保骨头、箭、腐肉、线、火药等基础物资持续供应。</li><li>优化完全遵循原版生成规则，只调整生成频率与利用率，<strong>无魔改、不破坏平衡</strong>，让空岛生存资源更充足、更流畅。</li></ul><h3 id="🛡️-安全与公平" tabindex="-1">🛡️ 安全与公平 <a class="header-anchor" href="#🛡️-安全与公平" aria-label="Permalink to &quot;🛡️ 安全与公平&quot;">​</a></h3><ul><li>你的岛屿完全私有，非授权玩家无法破坏或拿东西。</li><li>岛主可以随时设置权限，防止意外或恶意行为。</li><li>服务器定期备份，岛屿数据永不丢失。</li></ul><h2 id="📖-常用指令速查" tabindex="-1">📖 常用指令速查 <a class="header-anchor" href="#📖-常用指令速查" aria-label="Permalink to &quot;📖 常用指令速查&quot;">​</a></h2><table tabindex="0"><thead><tr><th>指令</th><th>作用</th></tr></thead><tbody><tr><td><code>/is create</code></td><td>创建新岛屿</td></tr><tr><td><code>/is delete</code></td><td>删除当前岛屿（需二次确认）</td></tr><tr><td><code>/is setspawn</code></td><td>设置岛屿重生点</td></tr><tr><td><code>/is spawn</code></td><td>传送回岛屿</td></tr><tr><td><code>/is setperms</code></td><td>设置岛屿权限（表单操作）</td></tr><tr><td><code>/is invite &lt;玩家名&gt;</code></td><td>邀请玩家加入</td></tr><tr><td><code>/is kick &lt;玩家名&gt;</code></td><td>踢出成员（仅岛主）</td></tr><tr><td><code>/is biome</code></td><td>修改岛屿生物群系</td></tr><tr><td><code>/is tip</code></td><td>自定义欢迎语和底部提示</td></tr><tr><td><code>/is help</code></td><td>显示帮助</td></tr></tbody></table><blockquote><p>💡 直接打开钟表菜单 <code>/cd</code> 可以直接操作，非常方便！</p></blockquote><h2 id="🌟-更多玩法等你探索" tabindex="-1">🌟 更多玩法等你探索 <a class="header-anchor" href="#🌟-更多玩法等你探索" aria-label="Permalink to &quot;🌟 更多玩法等你探索&quot;">​</a></h2><ul><li><strong>挑战系统</strong>：完成不同等级的任务，获取稀有奖励。</li><li><strong>玩家商店</strong>：与其他人交易物资，货币通用。</li><li><strong>维度探索</strong>：探索其他维度，寻找资源。</li></ul><p>快邀请你的朋友，一起创造属于你们的天空之城吧！</p><hr><p><em>有任何问题或建议，欢迎在群里提出，祝你玩得开心！</em></p>',27)]))}const b=e(r,[["render",l]]);export{g as __pageData,b as default};
